ats <- function(weights) {\n","  stats <- list(\n","    mean = mean(weights, na.rm = TRUE),\n","    median = median(weights, na.rm = TRUE),\n","    sd = sd(weights, na.rm = TRUE),\n","    min = min(weights, na.rm = TRUE),\n","    max = max(weights, na.rm = TRUE)\n","  )\n","  return(stats)\n","}\n","\n","# ফাংশন ব্যবহার\n","cat(\"\\nওজনের পরিসংখ্যান:\\n\")\n","weight_stats <- calculate_stats(data$weight)\n","print(weight_stats)"]}],"metadata":{"kaggle":{"accelerator":"none","dataSources":[],"isGpuEnabled":false,"isInternetEnabled":true,"language":"r","sourceType":"notebook"},"kernelspec":{"display_name":"R","language":"R","name":"ir"},"language_info":{"codemirror_mode":"r","file_extension":".r","mimetype":"text/x-r-source","name":"R","pygments_lexer":"r","version":"4.4.0"},"papermill":{"default_parameters":{},"duration":7.063204,"end_time":"2025-12-27T16:37:05.877694","environment_variables":{},"exception":null,"input_path":"__notebook__.ipynb","output_path":"__notebook__.ipynb","parameters":{},"start_time":"2025-12-27T16:36:58.81449","version":"2.6.0"}},"nbformat":4,"nbformat_minor":5}